<?php

declare(strict_types=1);namespace backend\controllers;use backend\components\AdminController;use common\models\Slide;use Yii;use yii\data\ActiveDataProvider;use yii\web\NotFoundHttpException;
final class SlideController extends AdminController { protected string $permission='manageContent'; public function actionIndex():string{return $this->render('index',['dataProvider'=>new ActiveDataProvider(['query'=>Slide::find()->orderBy(['sort'=>SORT_ASC])])]);}public function actionCreate(){return $this->edit(new Slide(['enabled'=>1,'sort'=>100]));}public function actionUpdate(int $id){return $this->edit($this->find($id));}public function actionDelete(int $id){if(Yii::$app->request->isPost)$this->find($id)->delete();return $this->redirect(['index']);}private function edit(Slide $m){if($m->load(Yii::$app->request->post())&&$m->save())return $this->redirect(['index']);return $this->render('form',['model'=>$m]);}private function find(int $id):Slide{$m=Slide::findOne($id);if(!$m)throw new NotFoundHttpException();return $m;}}
